// El CTA de cantidad+CP NO va si la sesión ya cotizó. El lead ya dio esos dos datos y
// volvérselos a pedir es justo lo que reporta el test de paridad.
//
// Por qué mirar la SESIÓN y no el turno: el filtro `yaCotizo` de `Partir en burbujas` ya
// tapa el caso del mismo turno, pero no llega acá. Cuando el Recolector no corre (el
// clasificador `¿Consulta especial?` responde `no` para un «¿cuánto cuestan?» suelto), el
// flujo sale por `Recuperar cards` y SALTEA `Partir en burbujas` por completo, así que ese
// filtro no se ejecuta nunca en esa rama.
//
// `ya_cotizo` lo resuelve `Leer evento` contra el historial. isExecuted por la misma razón
// que el resto de este nodo: referenciar un nodo que no corrió tira ExpressionError.
const _le3 = $('Leer evento');
const yaCotizoSesion = _le3.isExecuted ? !!(_le3.first().json || {}).ya_cotizo : false;

if (step === 'step_2' && dinamico) {
  partes.unshift({ texto: dinamico, adjuntos: [] });
} else if (step === 'step_3' && !yaCotizoSesion) {
  partes.push({ texto: CTA_STEP_3, adjuntos: [] });
}

